import{_ as t,c as r,a2 as o,o as a}from"./chunks/framework.CoXjB5sU.js";const n="/assets/CreateReportsMain.CJIfsUYv.png",s="/assets/CreateReportsNew2.CLAMRObJ.png",i="/assets/CreateReportsSupportingInformation.CGoOtbdN.png",p="/assets/CreateReportsNewButton.Bb4-Bg_F.png",c="/assets/CreateReportsNewResult.BtJptRTx.png",R=JSON.parse('{"title":"Generating reports","description":"","frontmatter":{},"headers":[],"relativePath":"doc/guides/usage/generating-reports.md","filePath":"doc/guides/usage/generating-reports.md"}'),l={name:"doc/guides/usage/generating-reports.md"};function d(g,e,h,m,u,f){return a(),r("div",null,e[0]||(e[0]=[o('<h1 id="generating-reports" tabindex="-1">Generating reports <a class="header-anchor" href="#generating-reports" aria-label="Permalink to &quot;Generating reports&quot;">​</a></h1><h2 id="user-reports-list" tabindex="-1">User reports&#39; list <a class="header-anchor" href="#user-reports-list" aria-label="Permalink to &quot;User reports&#39; list&quot;">​</a></h2><p>Along with navigation and search, there is another tab called <em>Reports</em>. This is responsible for storing and managing user-generated reports.</p><p><img src="'+n+'" alt="Report manager tab"></p><p>The list shows each report with its name, description, type and creation date. Double click on any row to reopen the report editor.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>The current version of ioChem-BD has the following reports activated: <em>Supporting information</em>, <em>Reaction energy profile</em> and <em>Reaction graph</em>.</p></div><h2 id="creating-a-report" tabindex="-1">Creating a report <a class="header-anchor" href="#creating-a-report" aria-label="Permalink to &quot;Creating a report&quot;">​</a></h2><p>Reports are created from the <strong>My workspace</strong> tab and stored inside the project that contains their calculations:</p><ol><li>Right click on the destination project in the workspace tree.</li><li>Choose <strong>Generate report</strong> from the context menu.</li><li>Select the report type: <em>Supporting Information</em>, <em>Reaction Energy Profile</em> or <em>Reaction Graph</em>.</li></ol><p><img src="'+s+'" alt="Generating a report from the context menu"></p><p>A new tab opens with the report form, and the report is added to the project tree with the <em>REP</em> type code.</p><h2 id="report-page" tabindex="-1">Report page <a class="header-anchor" href="#report-page" aria-label="Permalink to &quot;Report page&quot;">​</a></h2><p>We can split the report&#39;s content into three sections:</p><ul><li><em>Report details</em>: Define general report fields; name and description are for internal Create module usage, the title field is for the report header.</li><li><em>Report selected calculations</em>: A list of calculations associated to this report, populated with the calculations of the project by default. We can order them by using drag-and-drop, set a name for each calculation or even remove them from this list. The <strong>Add Navigation selected calculations</strong> button appends the calculations currently selected in the workspace tree.</li><li><em>Report configuration</em>: The right section of this form contains the specific report configuration; it varies depending on the report type being used.</li></ul><p><img src="'+i+'" alt="Supporting information report form"></p><p>Once all report parameters are set, use the operation buttons under the report configuration section: <strong>Generate</strong>, <strong>Save</strong> and <strong>Save and close</strong>.</p><p><img src="'+p+'" alt="Report operation buttons"></p><p>A single click on the <em>Generate</em> button will create the report and start its download on the user&#39;s web browser as a PDF document.</p><p><img src="'+c+'" alt="Report PDF output example"></p>',19)]))}const _=t(l,[["render",d]]);export{R as __pageData,_ as default};
